// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2018, "8-9", [{"author":"А. Пиперски","question":"Саша и Аня стоят в Петербурге на Невском проспекте возле станции метро «Гостиный двор» и думают, как им добираться до соседней станции «Маяковская».\n— На метро поедем или пешком пойдём? — спрашивает Саша.\n— Давай …, — отвечает Аня.","choices":["<em>прогуляем</em>","<em>прогуляемся</em>","<em>разгуляемся</em>","<em>загуляем</em>","<em>гульнём</em>."],"key":"Б","review":["Соседняя станция","От метро до метро можно дойти пешком, и Аня предлагает пройтись вместе с Сашей.","Для такого предложения подходит «Давай прогуляемся». «Прогуляем» обычно требует дополнения, например «прогуляем урок»."]},{"author":"Б. Иомдин","question":"В какой паре даны синонимы?","choices":["<em>булочная — булочка</em>","<em>колыбельная — колыбелька</em>","<em>гримёрная — гримёрка</em>","<em>накладная — накладка</em>","<em>уборная — уборка.</em>"],"key":"В","review":["Два близких названия","Посмотри, где слова называют один и тот же предмет или помещение. Уменьшительный суффикс сам по себе этого не гарантирует.","«Гримёрная» и «гримёрка» называют помещение, где артисты гримируются. «Булочная» и «булочка», например, называют магазин и выпечку."]},{"author":"Е. Бикмаев","question":"В каком слове основное ударение падает не на тот слог с конца слова, что в остальных?","choices":["<em>многоугольный</em>","<em>косоугольный</em>","<em>широкоугольный</em>","<em>краеугольный</em>","<em>каменноугольный</em>."],"key":"Д","review":["Ударение в длинных словах","Произнеси слова с общим фрагментом «угольный» и посчитай ударные слоги от конца.","«Многоуго́льный», «косоуго́льный», «широкоуго́льный» и «краеуго́льный» имеют ударение на предпоследнем слоге. В слове «каменноу́гольный» основное ударение на третьем слоге с конца."]},{"author":"Л. Фёдорова","question":"Что не может быть строением?","choices":["гостиница","столешница","больница","кузница","мельница."],"key":"Б","review":["Постройки и их названия","Некоторые названия обозначают помещения или здания с определённым назначением. Ищи слово, обозначающее часть предмета.","«Столешница» — верхняя плоскость стола или рабочая поверхность. Гостиница, больница, кузница и мельница могут называться зданиями."]},{"author":"Е. Бикмаев","question":"Какие два слова соотносятся по смыслу не так, как остальные?","choices":["<em>беженец — беженка</em>","<em>переселенец — переселенка</em>","<em>выходец — выходка</em>","<em>иностранец — иностранка</em>","<em>туземец — туземка.</em>"],"key":"В","review":["Соотношение двух слов","Сравни пары по схеме «мужчина — женщина». Так соотносятся, например, «беженец» и «беженка».","«Выходец» — человек родом откуда-либо, а «выходка» — его возможный поступок. В остальных парах оба слова называют людей."]},{"author":"Б. Иомдин и Ю. Халеева","question":"В каком примере слово <em>проглядывать</em> нельзя заменить на <em>просматривать</em>?","choices":["<em>Книги читают лишь старые дурни, число их день ото дня сокращается, люди проглядывают газеты и смотрят в стекло беспощадного ящика.</em> (Л. Зорин)","<em>Сначала — контрактники Внутренних войск МВД лениво проглядывали документы и тут же теряли к ним всякий интерес.</em> («Новая газета»)","<em>Иногда в стихах проглядывает и автор, с которым нам предстоит так обстоятельно познакомиться в рассказах Довлатова.</em> (А. Генис)","<em>На столе его лежал ворох всяких бумаг, которые я иногда бегло проглядывала, если его не было в кабинете.</em> (К. Сурикова)","<em>Когда получаю новый номер, проглядываю все статьи, обязательно прочитываю всё, что связано с политикой, экономическими проблемами.</em> («Дело»)"],"key":"В","review":["Значения глагола","В четырёх цитатах кто-то бегло читает газету, бумаги или другие тексты. В одной цитате глагол описывает того, кто сам становится заметен.","У Гениса в стихах «проглядывает автор», то есть в них видны черты автора. Подстановка «автор просматривает» создаёт другой смысл и требует назвать то, что он просматривает."]},{"author":"И. Иткин","question":"В какой из этих пар глаголы относятся к разным видам?","choices":["<em>соединить — соединиться</em>","<em>содержать — содержаться</em>","<em>состоять — состояться</em>","<em>сознавать — сознаваться</em>","ни в какой."],"key":"В","review":["Вид глагола в паре","Поставь к словам вопросы «что делать?» и «что сделать?». Прибавление «-ся» само по себе вида не определяет.","«Состоять» отвечает на вопрос «что делать?», «состояться» — «что сделать?». В остальных парах оба глагола отвечают на один и тот же вопрос."]},{"author":"Е. Бикмаев","question":"К какому слову можно добавить одну букву, чтобы получить его антоним?","choices":["<em>ослышаться</em>","<em>ослушаться</em>","<em>слышать</em>","<em>слышаться</em>","<em>слушать</em>."],"key":"Б","review":["Одна буква и новый смысл","Подумай, какая буква превратит глагол со значением непослушания в глагол со значением послушания.","Прибавляем «п» в начало «ослушаться» и получаем «послушаться». Первое слово означает нарушить требование, второе — выполнить его."]},{"author":"П. Аркадьев","question":"Омофонами называются слова, которые пишутся по-разному, а произносятся одинаково, например, <em>гнуться</em> и <em>гнутся</em>. У какого из приведённых слов есть омофон?","choices":["<em>рукой</em>","<em>ногой</em>","<em>головой</em>","<em>губой</em>","<em>теменем</em>."],"key":"Б","review":["Слова с одним звучанием","Рассмотри пары, в которых различались бы безударные «а» и «о». В произношении это различие может исчезнуть.","«Ного́й» и «наго́й» звучат одинаково. Первое — форма слова «нога», второе означает «обнажённый»."]},{"author":"А. Сомин","question":"Какая из этих последовательностей встречается в русских текстах значительно чаще, чем остальные?","choices":["<em>нам-нам</em>","<em>тебе-тебе</em>","<em>ему-ему</em>","<em>ей-ей</em>","<em>вам-вам</em>."],"key":"Г","review":["Повтор местоимения","Проверь, не образует ли какой-либо повтор самостоятельное разговорное выражение.","«Ей-ей» употребляют как заверение, близкое к «правда» или «честное слово». Поэтому этот повтор встречается и там, где речь не идёт о местоимении «ей»."]},{"author":"А. Сомин","question":"В школах Польши проводится конкурс по комбинаторике, алгоритмике и логике. Какое животное изображено на его логотипе?","choices":["панда","носорог","зебра","утконос","коала."],"key":"Д","review":["Эмблема конкурса","Попробуй найти название польского конкурса по сочетанию трёх дисциплин — комбинаторики, алгоритмики и логики.","Организатор называет конкурс KOALA и расшифровывает название через польские слова «kombinatoryka», «algorytmika», «logika». На эмблеме коала."]},{"author":"И. Иткин","question":"Сергей Михайлович Богомазов — замечательный советский поэт-песенник. А его далёкий предок, в честь которого род Богомазовых получил свою фамилию, скорее всего, был...","choices":["богачом","священником","иконописцем","бродячим музыкантом","очень везучим человеком."],"key":"В","review":["Фамилия от занятия","В старых фамилиях часто сохраняется прозвание по профессии. Разбери слово «богомаз» на части.","Богомазом называли человека, который пишет иконы. От этого прозвания могло произойти «Богомазов»."]},{"author":"С. Переверзева","question":"На какой из подчёркнутых вопросов можно ответить как «да», так и «нет»?","choices":["<em>Попал или хотел попасть?</em> // <em><u>Да вместе вы зачем</u>?</em> (А. Грибоедов)","<em>Что ты тих, как день ненастный?</em> // <em><u>Опечалился чему</u>?</em> (А. Пушкин)","<em>Мимо курица бежала</em> // <em>И посуду увидала:</em> // <em>«Куд-куда! Куд-куда! // <u>Вы откуда и куда</u>?!»</em> (К. Чуковский)","<em>И будешь сыт… Так до сырой могилы</em> // <em>Трудись, трудись… <u>но жить когда</u>?</em> (И. Никитин)","<em><u>А целовалась, бабушка</u>,</em> // <em><u>Голубушка, со сколькими</u>?</em> (М. Цветаева)"],"key":"Б","review":["Ответ на вопрос","Замени каждое вопросительное слово тем, о чём спрашивают. Например, на «зачем?» отвечают указанием цели.","На «Опечалился чему?» можно сказать «Да, опечалился» или «Нет, не опечалился». Вопрос значит «опечалился чему-нибудь?». У Цветаевой же весь вопрос о количестве людей, даже если отдельно взять его первую часть."]},{"author":"Е. Бикмаев","question":"В текстах иногда встречается слово <em>зряшный</em>. Что оно значит?","choices":["заметный","проницательный","случайный","напрасный","видящий."],"key":"Г","review":["Значение редкого слова","Сравни «зряшный» с привычным «зря». Как можно описать усилие, потраченное зря?","«Зряшное усилие» — напрасное, бесполезное усилие. «Зряшный» в данном случае значит «напрасный»."]},{"author":"И. Иткин","question":"Даны слова, которые можно понять как существительное и как деепричастие. В каком случае эти существительное и деепричастие образованы от разных корней?","choices":["<em>перегрев</em>","<em>перепев</em>","<em>перелив</em>","<em>перерыв</em>","среди вариантов (А)–(Г) нет правильного."],"key":"Г","review":["Одно слово, разные корни","Восстанови глагол для каждого деепричастия и сравни его с глаголом, который дал существительное.","Существительное «перерыв» связано с «перервать», деепричастие «перерыв» — с «перерыть». Для «перегрев», «перепев» и «перелив» две формы связаны с одним и тем же глаголом."]},{"author":"Б. Иомдин","question":"<em>— Времени у нас мало, так что перейду сразу к делу, — говорила Тётя, бросаясь с места в карьер</em> (М. Кучерская). А о ком изначально говорили «бросаться с места в карьер»?","choices":["о курьерах","о геологах","о лошадях","о зайцах","о карьеристах."],"key":"В","review":["С места в карьер","В старом смысле «карьер» называл способ движения. Вспомни слова «рысь» и «галоп».","Карьер — очень быстрый галоп. Первоначально «броситься с места в карьер» могла лошадь, сразу перейдя к быстрому бегу."]},{"author":"С. Сай","question":"Во фрагменте сочинённой Юлием Кимом детской песенки мы пропустили шесть слов: <em>Ах, как _____ и _____! Ах, как _____ и _____! Ах, как _____ и _____!</em> Все слова, предложенные в ответах, используются на месте пробелов. А что из перечисленного нужно использовать на месте пробелов не один, а два раза?","choices":["<em>смешно</em>","<em>страшно</em>","<em>темно</em>","<em>тихо</em>","<em>чудно</em>."],"key":"Д","review":["Строчки из песенки","Слова соотносятся с настроением сказки. «Тихо» можно соединить с «темно», а «страшно» — со «смешно».","В песенке Кима сочетания «страшно и смешно» и «тихо и темно» используют четыре слова по разу. «Чудно» повторяется дважды и допускает разные ударения."]},{"author":"Л. Фёдорова","question":"Что из этого нельзя встретить в грамотно написанном тексте?","choices":["<em>заранее</em>","<em>зараннее</em>","<em>за раннее</em>","<em>за ранее</em>","все написания (А)–(Г) возможны."],"key":"Б","review":["Написание в контексте","Для раздельных вариантов составь сочетания с дополнительным словом. Например, «за ранее назначенную встречу».","Пишут «подготовиться заранее», «поблагодарить за раннее предупреждение», «за ранее оказанную помощь». Слитного написания «зараннее» с двумя «н» в норме нет."]},{"author":"С. Сай","question":"Послелогами называют такие слова, которые играют ту же роль, что предлоги, но стоят после того существительного, к которому относятся, а не перед ним. Какое слово, по мнению некоторых учёных, может употребляться как послелог в русском языке?","choices":["<em>через</em>","<em>по</em>","<em>позже</em>","<em>потом</em>","<em>спустя</em>."],"key":"Д","review":["Предлог после слова","Попробуй переставить слово с места перед обозначением времени на место после него.","Можно сказать «спустя час» и «час спустя». Во втором случае «спустя» относится к уже названному слову «час» и стоит после него."]},{"author":"Л. Фёдорова","question":"Какое наречие восходит к глагольной форме?","choices":["<em>почти</em>","<em>ровно</em>","<em>вполне</em>","<em>сразу</em>","<em>кстати</em>."],"key":"А","review":["Происхождение наречия","Поищи форму, которую можно было бы понять как побуждение к действию. Её старое значение может отличаться от современного.","«Почти» восходит к повелительной форме глагола «почесть» в значении «сосчитать, признать за что-либо». Из этой формы развилось значение «приблизительно, чуть меньше»."]},{"author":"И. Иткин","question":"Какое слово в этом отрывке из поэмы Э. Багрицкого «Дума про Опанаса» (1926), скорее всего, произносится не так, как сейчас?\n<em>Балта — городок приличный,\nГородок что надо.\nНет нигде румяней вишни,\nСлаще винограда.\n\nВ брынзе, в кавунах, в укропе\nЗвонок день базарный;\nГолубей гоняет хлопец\nС каланчи пожарной...</em>\nПримечание. <em>Кавуны</em> — арбузы.","choices":["<em>приличный</em>","<em>винограда</em>","<em>брынзе</em>","<em>звонок</em>","<em>каланчи</em>."],"key":"А","review":["Рифмы у Багрицкого","Сопоставь концы строк в каждом четырёхстишии. У слова «приличный» есть рифма в третьей строке.","«Приличный» рифмуется с «вишни», если читать сочетание «чн» в «приличный» как [шн]. Современное обычное произношение — с [чн]."]},{"author":"А. Пиперски","question":"Слова <em>каша</em>, <em>кефир</em>, <em>масло</em>, <em>молоко</em>, <em>сахар</em> и <em>соль</em> в абсолютном большинстве словарей русского языка следуют именно в таком порядке. А вот в «Грамматическом словаре русского языка» А. А. Зализняка они располагаются так: <em>каша</em>, <em>молоко</em>, <em>масло</em>, <em>сахар</em>, <em>кефир</em>, <em>соль</em>. Где в этом словаре стоит слово <em>хлеб</em>?","choices":["между словами <em>каша</em> и <em>молоко</em>","между словами <em>молоко</em> и <em>масло</em>","между словами <em>масло</em> и <em>сахар</em>","между словами <em>сахар</em> и <em>кефир</em>","между словами <em>кефир</em> и <em>соль</em>."],"key":"А","review":["Порядок в словаре","Выпиши последние буквы слов в порядке словаря Зализняка. Если две последние одинаковы, сравни предпоследние.","«Каша» оканчивается на «а», а «молоко» и «масло» — на «о». У «хлеб» последняя буква «б», поэтому слово стоит между «каша» и «молоко»."]},{"author":"Е. Бикмаев","question":"Какие из буквосочетаний могут быть и приставкой, и словом служебной части речи, и словом самостоятельной части речи: <em>бес</em>, <em>воз</em>, <em>надо</em>, <em>низ</em>, <em>раз</em>?","choices":["<em>бес</em> и <em>надо</em>","<em>воз</em> и <em>низ</em>","<em>надо</em> и <em>раз</em>","<em>бес</em> и <em>раз</em>","только <em>раз</em>."],"key":"В","review":["Приставки и отдельные слова","Для каждого сочетания подбери слово с такой приставкой, отдельное служебное слово и самостоятельное слово.","«Надо» есть в «надорвать», «надо мной» и «мне надо». «Раз» есть в «разбить», «раз ты пришёл» и «один раз». У «бес», «воз» и «низ» нет всех трёх употреблений."]},{"author":"С. Сай","question":"Какое утверждение о форме <em>некем</em> верно?","choices":["это форма местоимения <em>некто</em>","это форма местоимения <em>некий</em>","это либо форма местоимения <em>некто</em>, либо форма местоимения <em>некий</em>","это форма местоимения, у которого отсутствует форма именительного падежа","такой формы в русском литературном языке нет."],"key":"Г","review":["Местоимение в одной форме","Построй предложение с «некем» и замени творительный падеж другим падежом того же слова.","«Мне некем тебя заменить», «мне некого звать», «мне некому помочь» — формы одного отрицательного местоимения. Именительного падежа у него нет."]},{"author":"С. Переверзева","question":"Перед вами — цитата из пьесы Тирсо де Молины «Севильский озорник, или Каменный гость» в переводе Ю. Корнеева:\n<em>В полумиле с небольшим\nОт столицы португальской\nРасположен древний Белен,\nМонастырь, где проживает\nБратья, чтящ__ святого…</em>\nКакие буквы мы пропустили?","choices":["<em>ие</em>","<em>его</em>","<em>ее</em>","<em>ая</em>","<em>ия</em>."],"key":"Г","review":["Связь причастия со словом","Найди слово, к которому относится «чтящ__», и проверь, в каком числе стоит сказуемое «проживает».","Здесь «братья» — старое существительное женского рода со значением «братия, монашеское сообщество». Оно согласуется в единственном числе. Поэтому «проживает братья, чтящая святого»."]},{"author":"Л. Фёдорова","question":"В какой паре следует поменять порядок слов?","choices":["<em>притягательный — притяжательный</em>","<em>родительный — родительский</em>","<em>уступительный — наступательный</em>","<em>назывной — названный</em>","<em>противительный — противный</em>."],"key":"А","review":["Порядок в паре","Ищи в каждом сочетании название грамматического термина — падежа, союза или вида предложения.","В остальных парах термин стоит первым: «родительный падеж», «уступительное придаточное», «назывное предложение», «противительный союз». «Притяжательное прилагательное» требует переставить слова в первой паре."]},{"author":"Е. Бикмаев","question":"У четырёх из пяти этих глаголов, кроме инфинитива (неопределённой формы), есть ещё одна форма, оканчивающаяся на <em>-ться</em>. У какого глагола нет такой формы?","choices":["<em>пятиться</em>","<em>охотиться</em>","<em>тратиться</em>","<em>отметиться</em>","<em>выкатиться</em>."],"key":"Д","review":["Две формы на «-ться»","Проверь, как звучит команда одному человеку. Она тоже может оканчиваться на «-ться».","Получаются «пяться», «охоться», «траться», «отметься». Повелительная форма «выкатись» оканчивается иначе."]},{"author":"С. Сай","question":"Какая из перечисленных букв обычно не встречается перед <em>-ий</em> в конце начальной формы прилагательных?","choices":["<em>ж</em>","<em>б</em>","<em>в</em>","<em>г</em>","<em>д</em>."],"key":"Д","review":["Буква перед «-ий»","Подбери прилагательные на «-ий» для каждой буквы, проверяя именно две последние буквы основы с окончанием.","Есть «божий», «рыбий», «вдовий», «строгий». Сочетание «дий» в конце начальной формы прилагательного для русского языка нехарактерно."]},{"author":"Б. Иомдин","question":"Какой из этих примеров, встретившихся в интернете, соответствует литературной норме?","choices":["<em>И плывут по волнам нашей памяти,\nСловно кадры немого кино,\nЯнварей серебристые замети,\nСентябрей золотые руно</em>.","<em>Я по-прежнему тот же Кавалер ордена Золотого Руно</em>.","<em>Те же, словно чудовища Сцилла и Харибда, поджидают его на трудном пути к заветному «золотому руно».</em>","<em>Сын царя и правнук бога ветров Ясон собрал героев со всей Эллады, чтобы отправиться в путь за шкурой золотого барана — золотым руно</em>.","Ни один пример не соответствует норме."],"key":"Д","review":["Формы слова «руно»","Просклоняй «руно» по образцу «окно» и подставь формы, которые требуют соседние слова.","Нужны «золотые руна», «ордена Золотого Руна», «к золотому руну» и «за золотым руном». Во всех четырёх примерах оставили неправильную форму «руно»."]},{"author":"И. Иткин","question":"Даны некоторые итальянские слова: <em>cartone</em> [картонэ] ‘картон’, <em>ceramica</em> [чэрамика] ‘керамика’, <em>circo</em> [чирко] ‘цирк’, <em>di</em> [ди] ‘название буквы <em>d</em>’, <em>emme</em> [эммэ] ‘название буквы <em>m</em>’, <em>erre</em> [эррэ] ‘название буквы <em>r</em>’, <em>pi</em> [пи] ‘название буквы <em>p</em>’. Как по-итальянски называются буквы <em>c</em> и <em>n</em>?","choices":["<em>ci</em> [ки], <em>ni</em> [ни]","<em>ci</em> [чи], <em>enne</em> [эннэ]","<em>ecce</em> [эккэ], <em>enne</em> [эннэ]","<em>ecce</em> [эччэ], <em>ni</em> [ни]","<em>ca</em> [ка], <em>en</em> [эн]."],"key":"Б","review":["Названия итальянских букв","Сопоставь произношение «c» перед «i» со словом «circo». Для «n» ищи модель, похожую на название «m».","«Ci» звучит [чи]. Название «n» строится так же, как «emme»: согласная удваивается между двумя «e», получается «enne» [эннэ]."]}], {"year":2018,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2018-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
